const raw = $json.choices[0].message.content;
const withoutThinking = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
const jsonMatch = withoutThinking.match(/\{[\s\S]*\}/);
const cleaned = jsonMatch ? jsonMatch[0] : withoutThinking;
let data;
try {
  data = JSON.parse(cleaned);
} catch (e) {
  data = { title: 'Could not parse — check manually', org: '', type: 'Other', deadline: '', link: '', requirements: raw.slice(0, 200) };
}
const validTypes = ['Bursary', 'Internship', 'Graduate Program', 'Learnership', 'Other'];
if (!validTypes.includes(data.type)) {
  data.type = 'Other';
}
data.status = 'Not started';
data.added_on = $now.toFormat('yyyy-MM-dd');
data.chat_id = $('Classify Message').item.json.chat_id;
return [{ json: data }];

const msg = $json.message;
let type = 'text';
let content = '';

if (msg.photo && msg.photo.length > 0) {
  type = 'photo';
  content = msg.photo[msg.photo.length - 1].file_id;
} else if (msg.text && /^https?:\/\/\S+$/i.test(msg.text.trim())) {
  type = 'link';
  content = msg.text.trim();
} else {
  type = 'text';
  content = msg.text || msg.caption || '';
}

return [{ json: { type, content, chat_id: msg.chat.id } }];

const html = $json.data || $json.body || String($json);
   let text = html
     .replace(/<script[\s\S]*?<\/script>/gi, '')
     .replace(/<style[\s\S]*?<\/style>/gi, '')
     .replace(/<[^>]+>/g, ' ')
     .replace(/\s+/g, ' ')
     .trim();
   text = text.slice(0, 3000);

   return [{ json: { content: text, chat_id: $('Classify Message').item.json.chat_id } }];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
return [{ json: { image_base64: base64, chat_id: $('Classify Message').item.json.chat_id } }];

