const data = $json;
   data.dedup_key = (data.title + '|' + data.org).toLowerCase().replace(/\s+/g, ' ').trim();
   return [{ json: data }];

const items = $input.all();
const today = new Date();
today.setHours(0, 0, 0, 0);

let results = items.map(item => {
  const d = item.json;
  if (d.deadline) d.deadline = String(d.deadline).slice(0, 10);
  if (d.added_on) d.added_on = String(d.added_on).slice(0, 10);
  let daysLeft = '';
  if (d.deadline) {
    const dl = new Date(d.deadline);
    daysLeft = Math.round((dl - today) / 86400000);
  }
  const bucket = (daysLeft !== '' && daysLeft < 0 && d.status !== 'Submitted') ? 'expired' : 'active';
  return { json: { ...d, days_left: daysLeft, bucket } };
});

results.sort((a, b) => {
  const da = a.json.days_left === '' ? 999999 : a.json.days_left;
  const db = b.json.days_left === '' ? 999999 : b.json.days_left;
  return da - db;
});

return results;

const items = $input.all();
const urgent = items.filter(i => i.json.days_left !== '' && i.json.days_left <= 5 && i.json.days_left >= 0);

if (urgent.length === 0) {
  return [{ json: { send: false } }];
}

let msg = 'Closing within 5 days:\n\n';
urgent.forEach(i => {
  msg += `- ${i.json.title} (${i.json.org}) — ${i.json.days_left} day(s) left\n`;
});

return [{ json: { send: true, message: msg } }];

